create table users
(
    id                    uuid                     default gen_random_uuid()   not null
        primary key,
    email                 text                                                 not null,
    display_name          text,
    created_at            timestamp with time zone default now()               not null,
    age                   integer,
    gender                user_gender,
    preferred_sports      text[]                   default '{}'::text[],
    intent                user_intent,
    avatar_url            text                     default 'https://ekmhrxdwgegxkdkdukgq.supabase.co/storage/v1/object/public/post-images/male-1.png'::text,
    updated_at            timestamp with time zone default now(),
    sports                text[],
    phone                 text
        constraint users_phone_unique
            unique,
    phone_confirmed_at    timestamp with time zone,
    phone_confirmed       boolean                  default false,
    email_confirmed_at    timestamp with time zone,
    last_sign_in_at       timestamp with time zone,
    is_anonymous          boolean                  default false,
    onboarding_completed  boolean                  default false               not null,
    onboarding_step       text                     default 'phone_input'::text not null,
    language              text                     default 'en'::text,
    timezone              text                     default 'UTC'::text,
    notification_settings jsonb                    default '{}'::jsonb,
    privacy_settings      jsonb                    default '{}'::jsonb,
    skill_level           text                     default 'beginner'::text,
    games_played          integer                  default 0,
    bio                   text
);

comment on column users.display_name is 'Primary and only name field for the user (consolidated from previous name and full_name fields)';

comment on column users.age is 'User age (13-100)';

comment on column users.gender is 'User gender preference';

comment on column users.intent is 'User intent for using the platform';

comment on column users.avatar_url is 'User profile image URL';

comment on column users.sports is 'Array of sports the user is interested in';

comment on column users.onboarding_completed is 'Whether user has completed onboarding';

comment on column users.onboarding_step is 'Current onboarding step';

comment on column users.language is 'User preferred language (en/ar)';

comment on column users.timezone is 'User timezone';

comment on column users.notification_settings is 'User notification preferences';

comment on column users.privacy_settings is 'User privacy preferences';

alter table users
    owner to postgres;

create unique index users_email_lower_unique_idx
    on users (lower(email));

create index idx_users_phone
    on users (phone);

create index idx_users_email
    on users (email);

create index idx_users_age
    on users (age);

create index idx_users_gender
    on users (gender);

create index idx_users_sports
    on users using gin (sports);

create index idx_users_intent
    on users (intent);

create index idx_users_onboarding_completed
    on users (onboarding_completed);

create index idx_users_language
    on users (language);

grant delete, insert, references, select, trigger, truncate, update on users to anon;

grant delete, insert, references, select, trigger, truncate, update on users to authenticated;

grant delete, insert, references, select, trigger, truncate, update on users to service_role;

